    {
      "card_ids": ["C47"],
      "claim": "Niraparib, a fused heteroaromatic amide with a basic amine, has an absolute oral bioavailability of 72.7% in cancer patients; its high transfer score and shared amide/heteroaromatic/basic-amine features support high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Cabotegravir, a piperazine-containing heteroaromatic, shows near-complete oral bioavailability in humans; this directly supports high F for the query's piperazine-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Encainide, an amide/basic-amine drug, has an absolute oral bioavailability of 20-30% in healthy subjects, meeting the F>=20% threshold and supporting a high classification despite being at the lower end.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Alfuzosin, a heteroaromatic amide with a basic amine, has an absolute oral bioavailability of 64.5% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Cilomilast, a cyclopentyl-containing oral drug, is almost completely bioavailable (96%) in healthy volunteers, supporting high F for the cyclopentyl-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "ZL-2201, a structurally related heteroaromatic kinase-type compound, has a predicted human oral bioavailability of approximately 70%, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Pimodivir, a heteroaromatic oral drug, has approximately 46% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "SB-742457, a piperazine-containing heteroaromatic, demonstrated excellent oral bioavailability in phase III trials, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental analogues with high assay-transfer scores show oral bioavailability at or above 20%, mostly 30-100%, including structurally similar piperazine/heteroaromatic amides. No affirmative evidence supports F<20%, so the query is predicted high.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule itself.",
    "Most analogue values come from different therapeutic classes; transfer relies on high assay-transfer scores rather than identical scaffolds.",
    "A few records are qualitative (good/excellent) without numeric F values, adding minor uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

